"""Verify exact added IDs, fixed source inputs and unchanged delivered generated bytes."""
from pathlib import Path
import argparse,json,hashlib
from migration_generated_outputs import verify_generated_output_hashes
p=argparse.ArgumentParser();p.add_argument('--batch',required=True);p.add_argument('--baseline',required=True);p.add_argument('--admission',required=True);a=p.parse_args()
w=Path(__file__).resolve().parents[1];r=w/'artifacts'/('batch-'+a.batch);b=r/a.baseline;docs=w.parent/'docs'
read=lambda p:json.loads(p.read_text(encoding='utf-8-sig'))
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest().upper()
before=read(b/'manifest.json');after=read(w/'generated/manifest.json');admission=read(docs/a.admission)
admitted=[x for x in admission['declarations'] if x['decision']=='ADMITTED'];deferred=[x for x in admission['declarations'] if x['decision']=='DEFERRED'];pre=admission['prerequisites']
ids={x['stableId'] for x in admitted+pre}
assert len(ids)==len(admitted)+len(pre)
assert set(after['sourceStableIds'])-set(before['sourceStableIds'])==ids
unchanged,modified=verify_generated_output_hashes(
 {f['relativePath']:sha(b/'generated'/f['relativePath']) for f in before['files']},
 {f['relativePath']:sha(w/f['relativePath']) for f in after['files']},
 admission.get('affectedGeneratedFiles',[]))
identity=read(r/'sdk/source-identity.json')
for x in identity['files']:assert sha(r/'sdk'/x.get('localName',Path(x['path']).name))==x['sha256'],x
assert admission['sdkSourceIdentitySha256']==sha(r/'sdk/source-identity.json')
states={x['StableId']:x['State'] for x in read(b/'inventory.json')['FinalClassification']['Declarations']}
converted={x['stableId'] for x in admitted+pre if x.get('transition')=='ManualToEmitted'}
assert all(states[sid]==('Manual' if sid in converted else 'Blocked') for sid in ids)
report=dict(state='PASS',baseline=admission['baseline'],admitted=len(admitted),deferred=len(deferred),newPrerequisites=len(pre),reused=len(admission['reused']),addedStableIds=sorted(ids),manualStableIds=[],manualToEmittedStableIds=sorted(converted),newGeneratedSdkDeclarations=len(ids-converted),oldGeneratedFiles=unchanged,modifiedGeneratedFiles=modified,sdkSourceIdentitySha256=sha(r/'sdk/source-identity.json'),sdkSourceCommit=identity['commit'],admissionSha256=sha(docs/a.admission),admissionPath='docs/'+a.admission,newGeneratedFiles=[x['relativePath'] for x in after['files'] if x['relativePath'] not in {f['relativePath'] for f in before['files']}])
(r/'source-audit.json').write_text(json.dumps(report,indent=2)+'\n',encoding='utf-8')
print({k:report[k] for k in ['state','admitted','deferred','newPrerequisites','reused']})
